'use strict';
const $ = s => document.querySelector(s);
const e = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const coins = n => (n/100).toLocaleString(undefined,{maximumFractionDigits:2});
const usd = n => (n/10000).toLocaleString('en-US',{style:'currency',currency:'USD'});
const date = n => new Date(n).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
let selectedChild = '';
let childNavOpen=false;
let chartRange='ALL', chartAsset='', chartMode='gain';
let loadVersion = 0;
let S, page = 'overview', query = '', filter = 'all';
const paths = {overview:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',wallet:'M3 6h17v14H3z M3 6V4h14 M16 12h5v4h-5z',savings:'M5 10a7 7 0 0113-3l3 1v6l-3 1-1 5h-3v-3h-4v3H7l-1-5-3-2V9z M11 7h3',invest:'M3 20V4 M3 20h18 M7 14l4-4 4 2 6-8',chores:'M8 5H4v16h16V5h-4 M8 3h8v4H8z M8 13l3 3 6-6',cashout:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',store:'M3 9l2-6h14l2 6 M4 10v11h16V10 M3 9c0 4 6 4 6 0 0 4 6 4 6 0 0 4 6 4 6 0 M9 21v-7h6v7',history:'M4 5v5h5 M4 10a8 8 0 118 10 M12 7v5l3 2',bank:'M2 8l10-5 10 5z M4 21h16 M6 11v7 M12 11v7 M18 11v7',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L19 6',book:'M12 5v16 M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-4-1-7-1-10 1',coin:'M20 12a8 8 0 11-16 0 8 8 0 0116 0 M14 8h-3a2 2 0 000 4h2a2 2 0 010 4h-3 M12 6v12'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.coin}"/></svg>`;
const button = (text,action,id='',cls='') => `<button class="${cls}" data-action="${action}" data-id="${e(id)}">${text}</button>`;
const empty = (title,text,kind='coin') => `<div class="empty">${icon(kind)}<strong>${title}</strong>${text}</div>`;
const field = (name,title,type='text',value='',extra='') => `<label>${title}<input name="${name}" type="${type}" value="${e(value)}" ${extra} required></label>`;
const amountField = () => field('amount','Amount in __CURRENCY__','number','','min="0.01" max="100000000" step="0.01"');
const currencyText = text => String(text).replaceAll('__CURRENCY__',S?.settings?.coin_name||'Coins');
function localize(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode())walker.currentNode.textContent=currencyText(walker.currentNode.textContent)}
const parent = () => S?.user?.role === 'parent';
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500)}
async function api(path,data){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':S?.csrf||'','Idempotency-Key':Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('')},body:JSON.stringify({...data,...(S?.user?.role==='parent'&&S.child_id?{child_id:data.child_id??S.child_id}:{})})});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result}
async function load(){const version=++loadVersion;try{const r=await fetch('/api/state'+(selectedChild?'?child_id='+encodeURIComponent(selectedChild):''));const next=await r.json();if(version!==loadVersion)return;S=next;if(S.setup||S.login){selectedChild='';auth(S.setup);return}if(!r.ok)throw Error(S.error||'Unable to load your bank');selectedChild=String(S.child_id);render()}catch(err){$('#app').innerHTML=`<main class="auth"><h1>Couldn’t open your bank</h1><p>${e(err.message)}</p>${button('Try again','reload')}</main>`}}
function auth(setup){$('#app').innerHTML=`<main class="auth"><div class="brand"><span class="brand-mark">w</span>wealth trainer</div><h1>${setup?'Your family bank starts here.':'Welcome back.'}</h1><p class="subtitle">${setup?'Create your parent and child accounts.':'A little progress, every day.'}</p><form class="panel" id="auth-form" data-setup="${setup}">${setup?`${field('token','Setup token','password')}${field('parent_name','Parent name','text','Parent')}${field('parent_username','Parent username','text','','minlength="3" maxlength="32" pattern="[a-zA-Z0-9_.\\-]+" autocomplete="username"')}${field('parent_password','Parent password','password','','minlength="10" autocomplete="new-password"')}${field('child_name','Child name')}${field('child_username','Child username','text','','minlength="3" maxlength="32" pattern="[a-zA-Z0-9_.\\-]+" autocomplete="username"')}${field('child_password','Child password','password','','minlength="10" autocomplete="new-password"')}<p class="help">Use the setup token from your server configuration. Each password needs at least 10 characters.</p>`:`${field('username','Username','text','','autocomplete="username" autocapitalize="none" spellcheck="false"')}${field('password','Password','password','','autocomplete="current-password"')}`}<div class="error" role="alert"></div><button type="submit">${setup?'Create family bank':'Sign in'}</button></form><p class="help">100 __CURRENCY__ = $1.00 · Your private family economy</p></main>`;localize($('#app'))}
const navs = [['overview','Overview'],['chores','Earn __CURRENCY__'],['savings','Savings & goals'],['invest','Investments'],['store','Reward store'],['cashout','Cash out'],['history','Activity'],['book','Learn']];
function navigation(nav){const nested=['savings','invest','store','cashout'];const item=([id,name])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}${name}${parent()&&id==='chores'&&(S.pending_chores||[]).length?`<span class="nav-count" aria-label="${S.pending_chores.length} chores awaiting review">${S.pending_chores.length}</span>`:''}</button>`;if(!parent())return nav.map(item).join('');return nav.map(entry=>entry[0]==='savings'?`<details class="child-nav" id="child-nav" ${childNavOpen?'open':''}><summary>Child account</summary><div class="child-nav-items">${nav.filter(([id])=>nested.includes(id)).map(item).join('')}</div></details>`:nested.includes(entry[0])?'':item(entry)).join('')}
document.addEventListener('toggle',ev=>{if(ev.target.id==='child-nav')childNavOpen=ev.target.open},true);
function render(){const nav=parent()?[['overview','Child overview'],['chores','Chores'],['treasury','Bank funds'],['savings','Savings & goals'],['invest','Child portfolio'],['store','Reward store'],['cashout','Cash out'],['history','Money history'],['audit','Action log'],['book','Learn'],['bank','Parent controls']]:navs;if(!nav.some(n=>n[0]===page))page='overview';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">w</span>wealth trainer</div><p class="nav-label">Your family economy</p><nav class="nav" aria-label="Main navigation">${navigation(nav)}</nav><div class="sidebar-bottom"><div class="rate-card"><b>Small __CURRENCY__. Real possibilities.</b><span>100 __CURRENCY__ = $1.00 USD</span></div><div class="profile"><span class="avatar">${e(S.user.name.slice(0,1).toUpperCase())}</span><div><b>${e(S.user.name)}</b><small>${parent()?'Parent / Bank':'Young investor'}</small></div></div></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">Family bank <span aria-hidden="true">/</span> ${nav.find(n=>n[0]===page)[1]}</span><div class="actions">${parent()?`<label class="child-picker">Viewing child<select id="child-picker">${S.children.map(c=>`<option value="${c.id}" ${c.id===S.child_id?'selected':''}>${e(c.name)}</option>`).join('')}</select></label>`:''}<span class="pill">${parent()?'Parent account':'Child account'}</span>${button('Sign out','logout','','ghost small')}</div></header>${parent()&&page==='overview'?parentOverview():views[page]()}<p class="footer-note">100 __CURRENCY__ = $1.00 USD · Investments are simulated. __CURRENCY__ redemptions are fulfilled by your parent.</p></main></div>`;localize($('#app'))}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function txRows(rows,account){return rows.map(t=>{const amount=account?t[account]:(t.wallet||t.savings||t.held||0);return `<div class="row"><span class="tile-icon ${amount>=0?'green':''}">${icon(t.kind.startsWith('investment')?'invest':t.kind==='chore'?'chores':t.kind==='redemption'?'store':'history')}</span><div class="grow"><strong>${e(t.reason)}</strong><small>${date(t.at)}${parent()?' · '+e(t.actor_name)+' ('+e(t.actor_role)+')':''} · ${e(t.kind.replaceAll('-',' '))}${t.reversed?' · Reversed':''}</small></div><span class="amount ${amount>0?'positive':''}">${amount>0?'+':''}${coins(amount)} <small>__CURRENCY__</small></span></div>`}).join('')}
function overview(){const net=S.wallet+S.savings+S.invested+S.held;const pending=S.cashouts.filter(x=>x.status==='pending').length+S.completions.filter(x=>x.status==='pending').length+S.redemptions.filter(x=>x.status==='pending').length;return `${heading(parent()?`${e(S.child)}’s money, at a glance.`:`Hey ${e(S.user.name)}, keep growing.`,parent()?'A little earning. A little saving. A lifetime of good habits.':'Every __CURRENCY__ is a step toward something good.',parent()?button('+ Add __CURRENCY__','adjust'):button('Move to savings','transfer'))}<div class="overview-grid"><section class="wealth-card"><div><div class="eyebrow">Total net worth</div><div class="wealth-value">${coins(net)} <small>__CURRENCY__</small></div><p>${usd(net)} redemption value</p></div><div><div class="allocation" aria-hidden="true"><span></span><span></span><span></span></div><div class="wealth-footer"><span>${S.held?coins(S.held)+' __CURRENCY__ held for cash-out':'Earn. Save. Invest. Grow.'}</span><strong>Your future starts small.</strong></div></div></section><div class="balance-grid">${[['wallet','Available __CURRENCY__',S.wallet,''],['savings','Tucked away',S.savings,'green'],['invest','Working for you',S.invested,'purple']].map(([i,l,v,c])=>`<div class="balance-item"><span class="tile-icon ${c}">${icon(i)}</span><div class="info"><span>${l}</span><strong>${coins(v)}</strong></div><small>${usd(v)}</small></div>`).join('')}</div></div>${portfolioPanel()}<div class="content-grid"><div><section class="panel"><div class="panel-head"><h2>Recent activity</h2><button data-page="history">View all</button></div>${S.ledger.length?txRows(S.ledger.slice(0,4)):empty('A fresh start','Your first earned __CURRENCY__ will appear here.','history')}</section><section class="panel"><div class="panel-head"><h2>A little work, a little reward</h2><button data-page="chores">All chores</button></div>${S.chores.filter(x=>x.active).slice(0,3).map(c=>`<div class="row"><span class="tile-icon green">${icon('chores')}</span><div class="grow"><strong>${e(c.title)}</strong><small>Parent-approved earnings</small></div><span class="amount positive">+${coins(c.reward)}</span></div>`).join('')||empty('Room to earn',parent()?'Add your first chore in the parent bank.':'Your parent can add things to do.','chores')}</section></div><div><section class="panel"><div class="panel-head"><h2>${parent()?'Ready for your review':'Your investments'}</h2><button data-page="${parent()?'bank':'invest'}">${parent()?'Open bank':'Explore'}</button></div>${parent()?`<div class="stat-big">${pending} <small>pending requests</small></div><p class="subtitle">Cash-outs and optional chore or reward requests.</p>`:`<div class="stat-big ${S.profit>=0?'positive':'negative'}">${S.profit>=0?'+':''}${coins(S.profit)} <small>__CURRENCY__</small></div><p class="subtitle">Total investment gains and losses</p>`}</section>${parent()?`<section class="panel"><div class="panel-head"><h2>${e(S.child)}’s investment performance</h2><button data-page="invest">View portfolio</button></div><div class="stat-big ${S.profit>=0?'positive':'negative'}">${S.profit>=0?'+':''}${coins(S.profit)} <small>__CURRENCY__</small></div><p class="subtitle">${S.positions.length?(100*S.profit/S.positions.reduce((sum,p)=>sum+p.cost,0)).toFixed(2)+'% return on total invested __CURRENCY__':'No investments yet'}</p></section>`:''}<section class="learning"><div class="eyebrow">The money lesson</div><h2>Give your __CURRENCY__ time to grow.</h2><p>Savings earn interest. Then that interest can earn interest too. That’s compounding—and patience is the secret ingredient.</p></section></div></div>`}
function choreInbox(){const pending=S.pending_chores||[];return `<section class="panel"><div class="panel-head"><h2>Completed · waiting for you <span class="nav-count">${pending.length}</span></h2><span class="muted">All children</span></div>${pending.map(c=>`<div class="row"><span class="tile-icon green">${icon('chores')}</span><div class="grow"><strong>${e(c.title)}</strong><small>${e(c.child_name)} · ${coins(c.reward)} __CURRENCY__ · ${e(new Date(c.at).toLocaleString())}</small></div>${button('Accept & pay','chore-approve',c.id,'small')}${button('Send back','chore-revise',c.id,'ghost small')}${button('Decline','chore-decline',c.id,'ghost small')}</div>`).join('')||empty('All caught up','Completed chores appear here when a child taps I did it.','check')}<p class="help">Accepting pays the reward from your bank to the child who completed the chore.</p></section>`}
function chores(){return `${heading('Good work pays off.',parent()?'Chores assigned to '+e(S.child)+'. Review completed chores and pay rewards below.':'Complete a chore, ask for approval, and earn your __CURRENCY__.',parent()?button('+ Create chore','chore-save'):'')}${parent()?choreInbox():''}<div class="cards">${S.chores.filter(x=>x.active||parent()).map(c=>{const pending=S.completions.some(x=>x.chore===c.id&&x.status==='pending');return `<article class="item-card"><span class="tile-icon green">${icon('chores')}</span><div><h2>${e(c.title)}</h2><p>${c.active?(c.recurrence==='anytime'?'Whenever needed':e(c.recurrence)+' · Due '+e(c.due_date)):'Paused'}</p>${(()=>{const latest=S.completions.filter(x=>x.chore===c.id).at(-1);return latest?.status==='revision'?`<p class="revision-note">Please try again: ${e(latest.review_note)}</p>`:''})()}</div><div class="card-bottom"><span class="price">${coins(c.reward)} <small>__CURRENCY__</small></span>${parent()?button('Edit','chore-save',c.id,'secondary small'):pending?'<span class="pill pending">Awaiting approval</span>':c.recurrence!=='anytime'&&c.due_date>S.today?'<span class="pill">Available '+e(c.due_date)+'</span>':button('I did it','chore-complete',c.id,'small')}</div></article>`}).join('')||`<section class="panel full">${empty('No chores yet',parent()?'Create a chore and choose the reward.':'Your parent will add your first chore soon.','chores')}</section>`}</div>${S.completions.length?`<h2 class="section-title">Your completed chores</h2><section class="panel">${S.completions.slice().reverse().map(c=>`<div class="row"><div class="grow"><strong>${e(c.title)}</strong><small>${date(c.at)} · ${coins(c.reward)} __CURRENCY__</small>${c.review_note?`<small>${e(c.review_note)}</small>`:''}</div><span class="pill ${c.status}">${e(c.status)}</span></div>`).join('')}</section>`:''}`}
function savings(){return `${heading('Save for your future.','Make room for bigger possibilities.',button('Transfer __CURRENCY__','transfer'))}${goalsPanel()}<div class="split"><section class="panel"><div class="eyebrow">Savings account</div><p class="help">${coins(S.reserved_savings||0)} __CURRENCY__ reserved for goals · ${coins(S.savings-(S.reserved_savings||0))} freely available</p><div class="stat-big">${coins(S.savings)} <small>__CURRENCY__</small></div><p class="subtitle">${usd(S.savings)} redemption value</p><p class="apr">${e(S.settings.apr)}% annual interest</p><p class="help">Interest is calculated daily and added to your savings. Your parent sets the rate.</p></section><section class="learning"><div class="eyebrow">Compounding in action</div><h2>What could one year look like?</h2><div class="stat-big">${coins(Math.round(S.savings*Math.pow(1+Number(S.settings.apr)/36500,365)))} <small>__CURRENCY__</small></div><p>Illustration using your current savings and rate, with no deposits or withdrawals. Daily rounding means actual results may differ. Your parent can change the rate.</p></section></div><section class="panel"><div class="panel-head"><h2>Savings activity</h2></div>${txRows(S.ledger.filter(t=>t.savings!==0),'savings')||empty('Start a saving habit','Move a few __CURRENCY__ from your wallet to begin.','savings')}</section>`}
function investments(){const open=S.positions.filter(p=>!p.closed);return `${heading('Put your __CURRENCY__ to work.',(S.settings.learning_level==='intermediate'?'Intermediate: mixes and individual investments.':'Beginner: ready-made and parent-created mixes.'),parent()?button('Refresh prices','refresh-prices'):'')}<section class="panel"><div class="investment-total"><div><div class="eyebrow">Portfolio value</div><div class="stat-big">${coins(S.invested)} <small>__CURRENCY__</small></div></div><div><div class="eyebrow">All-time gain / loss · ${S.positions.length?(100*S.profit/S.positions.reduce((n,p)=>n+p.cost,0)).toFixed(2):'0.00'}%</div><div class="stat-big ${S.profit>=0?'positive':'negative'}">${S.profit>=0?'+':''}${coins(S.profit)} <small>__CURRENCY__</small></div></div></div>${open.map(p=>`<div class="row"><span class="tile-icon purple">${icon('invest')}</span><div class="grow"><strong>${e(p.name)}</strong><small>${(p.cost/10000).toLocaleString()} simulated shares · Invested ${coins(p.cost)} · ${date(p.opened)}</small></div><div><strong>${coins(p.value)} __CURRENCY__</strong><small class="${p.profit>=0?'positive':'negative'}">${p.profit>=0?'+':''}${(100*p.profit/p.cost).toFixed(2)}%</small></div>${button('Sell','sell',p.id,'ghost small')}</div>`).join('')||empty('Your portfolio is a blank canvas','Choose an investment below when you’re ready.','invest')}</section><h2 class="section-title">Choose an investment mix</h2><div class="cards mix-cards">${S.committees.filter(c=>c.enabled).map(c=>{const info={Aggressive:['Higher risk','More technology exposure, with bigger possible ups and downs.'],Balanced:['Medium risk','Stocks for growth, balanced with bonds.'],Defensive:['Lower risk','Mostly bonds, with a smaller share in stocks. Still able to lose value.']}[c.name]||['Parent-created','A custom mix chosen by your parent.'];return `<article class="item-card mix-card"><div class="actions"><span class="tile-icon purple">${icon('invest')}</span><span class="pill">${e(info[0])}</span></div><div><h2>${e(c.name)}</h2><p class="mix-description">${e(info[1])}</p></div><div class="allocation-list">${Object.entries(JSON.parse(c.allocations)).map(([id,w])=>`<div><span>${id==='cash'?'Uninvested cash':e(S.investments.find(i=>i.id==id)?.name||'Unknown')}</span><b>${Number(w).toLocaleString(undefined,{maximumFractionDigits:2})}%</b></div>`).join('')}</div><div class="mix-purchase"><p><strong>100 __CURRENCY__</strong> per starting share</p>${button('Buy shares','buy-committee',c.id,'secondary')}</div></article>`}).join('')||empty('No mixes available','Your parent can create a mix of investments.','bank')}</div>${parent()||S.settings.learning_level==='intermediate'?`<h2 class="section-title">Individual investments</h2><div class="cards">${S.investments.filter(i=>i.enabled).map(i=>`<article class="item-card"><div class="actions"><span class="tile-icon">${icon('invest')}</span><span class="pill">${e(i.risk)} risk</span></div><div><h2>${e(i.name)}</h2><p>${e(i.symbol)}</p></div><p>100 __CURRENCY__ per starting share · ${i.quote?'Quote updated '+e(i.quote.day):'Connecting to Yahoo Finance…'}</p>${button('Invest __CURRENCY__','buy',i.id,'secondary')}</article>`).join('')}</div>`:''}${S.positions.some(p=>p.closed)?`<h2 class="section-title">Sold investments</h2><section class="panel">${S.positions.filter(p=>p.closed).map(p=>`<div class="row"><div class="grow"><strong>${e(p.name)}</strong><small>Sold ${date(p.closed)}</small></div><strong>${coins(p.proceeds)} __CURRENCY__</strong></div>`).join('')}</section>`:''}`}
function store(){return `${heading('Something worth saving for.','Choose a reward. Your parent approves it before __CURRENCY__ are spent.',parent()?button('+ Add reward','reward-save'):'')}${parent()?`<section class="panel"><h2>Reward requests</h2>${reviewRows(S.redemptions,'redemption')||empty('All caught up','New reward requests will appear here.','check')}</section>`:''}<div class="cards">${S.rewards.filter(r=>r.active||parent()).map(r=>{const pending=S.redemptions.some(x=>x.reward===r.id&&x.status==='pending');return `<article class="item-card"><span class="tile-icon purple">${icon('store')}</span><div><h2>${e(r.title)}</h2><p>${r.active?'A reward for your effort':'Unavailable'}</p></div><div class="price">${coins(r.price)} <small>__CURRENCY__ · ${usd(r.price)}</small></div>${parent()?button('Edit reward','reward-save',r.id,'secondary'):pending?'<span class="pill pending">Requested</span>':button('Request reward','redeem',r.id,'secondary')}</article>`}).join('')||`<section class="panel full">${empty('Your reward shelf is ready',parent()?'Add an experience, a treat, or something to save for.':'Your parent will add rewards to choose from.','store')}</section>`}</div>${S.redemptions.length?`<h2 class="section-title">Reward requests</h2><section class="panel">${S.redemptions.slice().reverse().map(r=>`<div class="row"><div class="grow"><strong>${e(r.title)}</strong><small>${coins(r.price)} __CURRENCY__ · ${date(r.at)}</small></div><span class="pill ${r.status}">${e(r.status)}</span></div>`).join('')}</section>`:''}`}
function history(){const rows=S.ledger.filter(t=>(filter==='all'||t.kind===filter)&&t.reason.toLowerCase().includes(query.toLowerCase()));return `${heading('Every __CURRENCY__ has a story.','Your permanent record of earnings, saving, investing, and spending.',button('Export CSV','export','','ghost'))}<section class="panel"><div class="filters"><input id="search" aria-label="Search transactions" placeholder="Search activity…" value="${e(query)}"><select id="filter" aria-label="Filter transaction type"><option value="all">All activity</option>${[...new Set(S.ledger.map(t=>t.kind))].map(k=>`<option value="${k}" ${filter===k?'selected':''}>${e(k)}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Date</th>${parent()?'<th>Who</th>':''}<th>Wallet</th><th>Savings</th><th>Held</th>${parent()?'<th></th>':''}</tr></thead><tbody>${rows.map(t=>`<tr><td><b>${e(t.reason)}</b><small>#${t.id} · ${e(t.kind)}${t.reversed?' · Reversed':''}${t.reversal_of?' · Reverses #'+t.reversal_of:''}</small></td><td>${e(new Date(t.at).toLocaleString())}</td>${parent()?`<td>${e(t.actor_name)}<small>${e(t.actor_role)}</small></td>`:''}<td class="${t.wallet>0?'positive':''}">${t.wallet>0?'+':''}${coins(t.wallet)}</td><td class="${t.savings>0?'positive':''}">${t.savings>0?'+':''}${coins(t.savings)}</td><td>${coins(t.held||0)}</td>${parent()?`<td>${!t.reversed&&['adjustment','transfer','allowance','interest'].includes(t.kind)?button('Reverse','reverse',t.id,'ghost small'):''}</td>`:''}</tr>`).join('')}</tbody></table>${!rows.length?empty('No matching activity','Your transactions will appear here.','history'):''}</div></section>`}
function reviewRows(items,type){return items.filter(x=>x.status==='pending').map(x=>`<div class="row"><span class="tile-icon">${icon(type==='chore'?'chores':'store')}</span><div class="grow"><strong>${e(x.title)}</strong><small>${coins(x.reward??x.price)} __CURRENCY__ · ${date(x.at)}</small></div>${button('Approve',type+'-approve',x.id,'small')}${button('Decline',type+'-decline',x.id,'ghost small')}</div>`).join('')}
function bank(){return `${heading('You’re the bank.','Managing '+e(S.child)+'’s __CURRENCY__, requests, and savings.',button('+ Add or remove __CURRENCY__','adjust'))}${learningSettings()}${accountPanel()}${backupPanel()}<details class="optional-controls"><summary>Optional controls · chores, rewards, savings & investments</summary><div class="split"><section class="panel"><div class="panel-head"><h2>Savings & allowance</h2></div><form id="settings-form">${field('apr','Annual savings interest (%)','number',S.settings.apr,'min="0" max="100" step="0.01"')}${field('allowance','Weekly allowance (__CURRENCY__)','number',Number(S.settings.allowance)/100,'min="0" max="100000000" step="0.01"')}<p class="help">Next allowance: ${e(S.settings.allowance_next)} (UTC). Set to 0 to pause. Savings interest compounds daily.</p><div class="error" role="alert"></div><button type="submit">Save settings</button></form></section><section class="panel"><div class="panel-head"><h2>Manage your economy</h2></div><div class="row"><div class="grow"><strong>Chores</strong><small>Set a task and its reward.</small></div>${button('Create','chore-save','','secondary small')}</div><div class="row"><div class="grow"><strong>Reward store</strong><small>Choose what __CURRENCY__ can buy.</small></div>${button('Create','reward-save','','secondary small')}</div><div class="row"><div class="grow"><strong>Investment mixes</strong><small>Build a diversified mix.</small></div>${button('Create','committee-save','','secondary small')}</div><div class="row"><div class="grow"><strong>Investments</strong><small>Add a stock or ETF ticker.</small></div>${button('Create','investment-save','','secondary small')}</div></section></div><section class="panel"><div class="panel-head"><h2>Available investments · all children</h2></div>${S.investments.map(i=>`<div class="row"><div class="grow"><strong>${e(i.name)} · ${e(i.symbol)}</strong><small>${i.enabled?'Available':'Paused'} · ${i.quote?'Quote: '+e(i.quote.day):'No quote yet'}</small></div>${button('Edit','investment-save',i.id,'ghost small')}</div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Investment mixes · all children</h2></div>${S.committees.map(c=>`<div class="row"><div class="grow"><strong>${e(c.name)}</strong><small>${c.enabled?'Available':'Paused'} · Edits apply to new purchases only</small></div>${button('Edit','committee-save',c.id,'ghost small')}</div>`).join('')}</section></details>`}
function cashoutRows(review=false){return S.cashouts.filter(x=>!review||x.status==='pending').slice().reverse().map(x=>`<div class="row"><span class="tile-icon">${icon('cashout')}</span><div class="grow"><strong>${e(x.reason)}</strong><small>${coins(x.amount)} __CURRENCY__ · ${usd(x.amount)} · ${date(x.at)}</small></div>${x.status==='pending'?(review?button('Approve','cashout-approve',x.id,'small')+button('Decline','cashout-decline',x.id,'ghost small'):button('Cancel request','cashout-cancel',x.id,'ghost small')):`<span class="pill ${x.status}">${e(x.status)}</span>`}</div>`).join('')}
function cashout(){return `${heading(parent()?'Cash-out requests':'Turn your __CURRENCY__ into something real.',parent()?'Review requests from '+e(S.child)+'. Approve when you will pay the child.':'100 __CURRENCY__ = $1.00. Your parent pays approved cash-outs.',parent()?'':button('Request cash-out','cashout-request'))}<div class="split"><section class="panel"><div class="eyebrow">Available to cash out</div><div class="stat-big">${coins(S.wallet)} <small>__CURRENCY__</small></div><p class="subtitle">${usd(S.wallet)}</p></section><section class="panel"><div class="eyebrow">Waiting for approval</div><div class="stat-big">${coins(S.held)} <small>__CURRENCY__</small></div><p class="help">Requested __CURRENCY__ are held safely and cannot be spent twice. A declined or cancelled request returns them to your wallet.</p></section></div><section class="panel"><h2>Your cash-out requests</h2>${cashoutRows(parent())||empty('No cash-outs yet','When you’re ready, request any whole-__CURRENCY__ amount from your wallet.','cashout')}</section>`}
function accountPanel(){return `<section class="panel"><div class="panel-head"><h2>Family accounts</h2>${button('+ Add child','account-add','','secondary small')}</div>${S.accounts.map(a=>`<div class="row"><span class="avatar">${e(a.name[0])}</span><div class="grow"><strong>${e(a.name)}</strong><small>${e(a.username)} · ${e(a.role)}</small></div>${button('Edit account','account-save',a.id,'ghost small')}</div>`).join('')}</section>`}

function learningSettings(){return `<section class="panel"><h2>Currency & learning level</h2><form data-action="learning-settings">${field('coin_name','Family currency name','text',S.settings.coin_name||'Coins','maxlength="24"')}<label>${e(S.child)}'s learning level<select name="learning_level"><option value="beginner" ${S.settings.learning_level==='beginner'?'selected':''}>Beginner: investment mixes</option><option value="intermediate" ${S.settings.learning_level==='intermediate'?'selected':''}>Intermediate: mixes, individual investments & reports</option></select></label><p class="help">The currency name applies to the whole family. The learning level applies to the selected child. Existing investments remain available to view and sell.</p><div class="error" role="alert"></div><button type="submit">Save currency & level</button></form></section>`}
function learning(){return `${heading('Learn as you grow.','Build your skills one step at a time.')}<div class="cards"><section class="item-card"><h2>Understand percentages</h2><p>A simulated share starts at 100 __CURRENCY__. A 10% gain makes it worth 110. A 10% loss makes it worth 90. Return = (current value - starting value) / starting value x 100.</p></section><section class="item-card"><h2>Choose your mix</h2><p>Aggressive has more stocks and technology, with bigger possible swings. Balanced is the medium option, mixing stocks and bonds. Defensive has more bonds. All can lose value.</p></section><section class="item-card"><h2>Spread your investments</h2><p>Mix percentages show where a new purchase goes. 50% of 200 __CURRENCY__ is 100 __CURRENCY__. Prices change and the weights drift; these mixes do not automatically rebalance.</p></section></div>${parent()||S.settings.learning_level==='intermediate'?`<section class="panel"><h2>Company detective: 10-K and 10-Q</h2><p>A 10-K is a public company's annual report, with audited financial statements. A 10-Q is a quarterly update, generally with unaudited statements.</p><ol><li>Open <a href="https://www.sec.gov/search-filings" target="_blank" rel="noopener noreferrer">SEC EDGAR</a> and search for a US company name or ticker, such as AAPL.</li><li>Find the 10-K (annual reports) and 10-Q (quarterly reports) section. Open the latest report.</li><li>Read Business, Risk Factors, Management's Discussion and Analysis, and Financial Statements in the 10-K.</li><li>Compare revenue, profit, debt and cash flow with last year. Check the latest 10-Q for recent changes.</li></ol><p><a href="https://www.investor.gov/introduction-investing/getting-started/researching-investments/how-read-10-k" target="_blank" rel="noopener noreferrer">Investor.gov: How to read a 10-K</a> | <a href="https://www.investor.gov/introduction-investing/getting-started/researching-investments/using-edgar-research-investments" target="_blank" rel="noopener noreferrer">How to use EDGAR</a></p><h3>Try it with your parent</h3><p>What does the company sell? Is revenue growing? Is it profitable? What is its biggest risk? Find one reason to invest and one reason to wait. ETFs and crypto do not use the same company-report format.</p></section>`:'<section class="learning"><h2>Your next step</h2><p>Your parent can unlock Intermediate when you are ready for individual investments and company reports.</p></section>'}`}


function actionRows(items){return items.map(a=>`<div class="row"><span class="tile-icon">${icon('history')}</span><div class="grow"><strong>${e(a.action.replaceAll('-',' '))}${a.detail?' · '+e(a.detail):''}</strong><small>${e(a.actor_name||'System')} · ${e(a.actor_role||'system')} · ${e(new Date(a.at).toLocaleString())}</small></div></div>`).join('')}
function auditLog(){return `${heading(e(S.child)+"'s action log",'Successful child actions and parent changes affecting this child. Family-wide account changes are included.')}<section class="panel">${actionRows(S.audit||[])||empty('No new actions yet','Actions will appear here as your family uses the app.','history')}<p class="help">Latest 500 actions since this feature was enabled. Earlier financial activity is in Money history. Passwords and private form contents are never recorded here.</p></section>`}
function parentOverview(){const net=S.wallet+S.savings+S.invested+S.held,cost=S.positions.reduce((n,p)=>n+p.cost,0),pending=[...S.cashouts,...S.completions,...S.redemptions].filter(x=>x.status==='pending').length;return `${heading(e(S.child)+"'s progress",'Track progress, review completed chores and manage everyday money.')}${(S.pending_chores||[]).length?`<section class="panel"><div class="panel-head"><h2>${S.pending_chores.length} completed chores waiting for review</h2><button data-page="chores">Review & pay</button></div></section>`:''}${bankNotice()}${portfolioPanel()}<div class="cards">${[['Total value',coins(net)+' __CURRENCY__'],['Available',coins(S.wallet)+' __CURRENCY__'],['Savings',coins(S.savings)+' __CURRENCY__'],['Invested',coins(S.invested)+' __CURRENCY__'],['Investment return',(cost?100*S.profit/cost:0).toFixed(2)+'%'],['Requests awaiting review',pending]].map(([name,value])=>`<section class="item-card"><div class="eyebrow">${name}</div><div class="stat-big">${value}</div></section>`).join('')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>Recent money activity</h2><button data-page="history">Full history</button></div>${txRows(S.ledger.slice(0,8))||empty('No activity yet','This child has no transactions.','history')}</section><section class="panel"><div class="panel-head"><h2>Recent actions</h2><button data-page="audit">Full action log</button></div>${actionRows((S.audit||[]).slice(0,8))||empty('Watching for new activity','New child actions and parent changes will appear here.','history')}</section></div>`}

function treasury(){return `${heading('Your bank funds.','Money set aside in the parent bank, separate from every child account.',`<div class="actions">${button('+ Add money to bank','bank-fund')}${button('Transfer to child','bank-transfer','','secondary')}</div>`)}${bankNotice()}<section class="panel"><div class="eyebrow">Bank balance</div><div class="stat-big">${coins(S.bank_balance||0)} <small>__CURRENCY__</small></div><p>${usd(S.bank_balance||0)} equivalent</p><p class="help">Only the parent sees this balance and its history. Adding money here does not change a child's wallet. Giving money, approving chore rewards, allowances and savings interest use this balance. Automatic payments wait for sufficient funds. Cash-outs are paid to your child and do not refill the bank.</p></section><section class="panel"><h2>Bank history</h2>${(S.bank_funds||[]).map(t=>`<div class="row"><div class="grow"><strong>${e(t.reason)}</strong><small>${e(new Date(t.at).toLocaleString())}</small></div><strong>${t.amount>0?'+':''}${coins(t.amount)} __CURRENCY__</strong></div>`).join('')||empty('No bank funds yet','Add money to start your bank balance.','bank')}</section>`}

function portfolioPanel(){
 const holdings=Object.values(S.positions.filter(p=>!p.closed).reduce((a,p)=>{const x=a[p.name]||{name:p.name,cost:0,value:0};x.cost+=p.cost;x.value+=p.value;a[p.name]=x;return a},Object.create(null))).sort((a,b)=>b.value-a.value);
 if(chartAsset&&!holdings.some(h=>h.name===chartAsset))chartAsset='';
 const selected=holdings.find(h=>h.name===chartAsset), currentValue=selected?selected.value:S.invested, relevant=S.positions.filter(p=>!chartAsset||p.name===chartAsset),cost=chartMode==='gain'?relevant.reduce((n,p)=>n+p.cost,0):(selected?selected.cost:holdings.reduce((n,h)=>n+h.cost,0)),gain=chartMode==='gain'?relevant.reduce((n,p)=>n+p.profit,0):currentValue-cost,value=chartMode==='gain'?gain:currentValue;
 const cutoff=Date.now()-({'1D':1,'1W':7,'1M':30,'ALL':Infinity}[chartRange])*86400000;
 const points=(S.portfolio_history||[]).filter(p=>new Date(p.at).getTime()>=cutoff).map(p=>({at:p.at,value:chartMode==='gain'?(chartAsset?(p.gains?.[chartAsset]||0):(p.gain||0)):(chartAsset?(JSON.parse(p.assets)[chartAsset]||0):p.value)}));
 const W=960,H=250,L=80,R=20,T=20,B=35, values=points.map(p=>p.value),min=Math.min(...values, value),max=Math.max(...values,value),pad=Math.max((max-min)*.12,max*.005,100),low=chartMode==='gain'?min-pad:Math.max(0,min-pad),high=max+pad;
 const first=points.length?new Date(points[0].at).getTime():0,last=points.length?new Date(points.at(-1).at).getTime():0;
 const x=(p,i)=>points.length===1?(L+W-R)/2:L+(new Date(p.at).getTime()-first)/Math.max(1,last-first)*(W-L-R),y=v=>T+(high-v)/(high-low)*(H-T-B);
 const path=points.map((p,i)=>(i?'L':'M')+x(p,i).toFixed(2)+','+y(p.value).toFixed(2)).join(' ');
 const graph=points.length?`<svg class="portfolio-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${e(chartAsset||'Portfolio')} investment value over time"><title>${e(chartAsset||'Portfolio')} value in ${e(S.settings.coin_name||'Coins')}</title>${[0,.5,1].map(f=>{const v=low+(high-low)*f,yy=y(v);return `<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#e5eaf3"/><text x="${L-12}" y="${yy+4}" text-anchor="end">${coins(Math.round(v))}</text>`}).join('')}${points.length>1?`<path d="${path} L${x(points.at(-1),points.length-1)},${H-B} L${L},${H-B} Z" fill="#edf2ff"/><path d="${path}" fill="none" stroke="#214fdb" stroke-width="3" stroke-linejoin="round"/>`:''}${points.map((p,i)=>`<circle tabindex="0" cx="${x(p,i)}" cy="${y(p.value)}" r="${points.length===1?5:3}" fill="#214fdb"><title>${e(new Date(p.at).toLocaleString())}: ${coins(p.value)} ${e(S.settings.coin_name||'Coins')}</title></circle>`).join('')}<text x="${L}" y="${H-6}">${e(points.length?new Date(points[0].at).toLocaleDateString():'')}</text><text x="${W-R}" y="${H-6}" text-anchor="end">${e(new Date(points.at(-1).at).toLocaleString())}</text></svg>`:empty('No recorded values in this range','Choose a longer range or check back after the next market update.','invest');
 return `<section class="panel portfolio-panel"><div class="panel-head"><h2>${e(chartAsset||'Investment portfolio')}</h2><div class="chart-ranges">${['1D','1W','1M','ALL'].map(r=>`<button data-chart-range="${r}" aria-pressed="${chartRange===r}" class="${chartRange===r?'selected':''}">${r==='ALL'?'All':r}</button>`).join('')}</div></div><div class="portfolio-headline"><strong>${coins(value)} <small>__CURRENCY__</small></strong><span class="${gain>=0?'positive':'negative'}">${gain>=0?'+':''}${coins(gain)} (${cost?(100*gain/cost).toFixed(2):'0.00'}%)</span><small>${chartMode==='gain'?'Total investment gains, including sold holdings':'Unrealized gain / loss on current holdings'}</small></div><div class="chart-ranges"><button data-chart-mode="gain" aria-pressed="${chartMode==='gain'}">Investment gains</button><button data-chart-mode="value" aria-pressed="${chartMode==='value'}">Portfolio value</button></div>${graph}<p class="help">${chartMode==='gain'?'Investment gains include realized and unrealized gains. Deposits, purchases and withdrawals are not counted as profit or loss.':'Portfolio value includes purchases and sales as well as market movement.'}${points.length<2?' History starts with this update; more points appear as values are recorded.':''} Hover or focus a point for its value.</p><div class="panel-head"><h2>Investment breakdown</h2><button data-chart-asset="">Show total</button></div><div class="table-wrap"><table><thead><tr><th>Investment</th><th>Value</th><th>Gain / loss</th><th>Return</th><th>Portfolio weight</th></tr></thead><tbody>${holdings.map(h=>`<tr class="${chartAsset===h.name?'selected-holding':''}"><td><button class="holding-link" data-chart-asset="${e(h.name)}">${e(h.name)}</button><small>${(h.cost/10000).toLocaleString()} simulated shares</small></td><td>${coins(h.value)}</td><td class="${h.value>=h.cost?'positive':'negative'}">${h.value>=h.cost?'+':''}${coins(h.value-h.cost)}</td><td class="${h.value>=h.cost?'positive':'negative'}">${(100*(h.value-h.cost)/h.cost).toFixed(2)}%</td><td>${S.invested?(100*h.value/S.invested).toFixed(1):'0.0'}%</td></tr>`).join('')}</tbody></table></div>${!holdings.length?empty('No investments yet','Your holdings will appear here after your first purchase.','invest'):''}</section>`
}


function goalsPanel(){return `<section class="panel"><div class="panel-head"><h2>Savings goals</h2>${button('+ New goal','goal-save','','small')}</div><div class="cards">${(S.goals||[]).map(g=>`<article class="item-card"><h2>${e(g.title)}</h2><div><progress max="${g.target}" value="${g.saved}" aria-label="${e(g.title)} progress"></progress><p>${coins(g.saved)} / ${coins(g.target)} __CURRENCY__ · ${Math.min(100,100*g.saved/g.target).toFixed(0)}%</p></div>${g.match_percent?`<p>${g.match_percent}% parent reward when reached ${g.matched?'· Paid':''}</p>`:''}<div class="actions">${g.saved<g.target?button('Add savings','goal-contribute',g.id,'small'): '<span class="pill">Goal reached!</span>'}${g.saved?button('Release','goal-withdraw',g.id,'ghost small'):''}${button('Edit','goal-save',g.id,'ghost small')}${parent()&&g.saved>=g.target&&g.match_percent&&!g.matched?button('Pay matching reward','goal-match',g.id,'small'):''}</div></article>`).join('')||empty('What are you saving for?','Create a goal and put a little money toward it.','savings')}</div></section>`}
function bankNotice(){if(!parent()||!S.bank_needs)return '';const n=S.bank_needs,short=n.needed-S.bank_balance;if(short<=0)return '';return `<section class="panel bank-warning" role="status"><h2>Bank needs ${coins(short)} more __CURRENCY__</h2><p>Pending chore rewards: ${coins(n.pending_rewards)} · Allowances due through the next 7 days: ${coins(n.allowances)}. Bank available: ${coins(S.bank_balance)}.</p><button data-page="treasury">Add bank funds</button></section>`}
function backupPanel(){return `<section class="panel"><h2>Backups & recovery</h2><p>Automatic daily backups keep the latest 14 copies in the project's backups folder, outside the Docker data volume.</p><p>${S.settings.backup_last?'Last successful backup: '+e(new Date(S.settings.backup_last).toLocaleString()):'First backup pending.'}</p>${S.settings.backup_error?`<p class="error">${e(S.settings.backup_error)}</p>`:''}${button('Back up now','backup-now','','secondary')}<p class="help">Copy this folder to another device for protection against computer failure.</p><details><summary>Forgot the parent password?</summary><p>On this computer, run Recover-Parent.ps1 from the project folder, or run:</p><code>docker compose exec wealth-trainer python -m app.manage recover-parent</code><p>Enter a new password twice. Family balances are kept; old parent sessions are signed out.</p></details></section>`}

const views={overview,chores,savings,invest:investments,store,cashout,history,bank,book:learning,audit:auditLog,treasury};
function modal(title,description,fields,action,id='',submit='Confirm'){ $('#dialog-content').innerHTML=`<h2>${title}</h2><p>${description}</p><form id="action-form" data-action="${action}" data-id="${e(id)}">${fields}<div class="error" role="alert"></div><div class="actions"><button type="submit">${submit}</button><button type="button" class="ghost" data-action="close">Cancel</button></div></form>`;localize($('#dialog-content'));$('#dialog').showModal() }
function openAction(action,id){let row;if(action==='goal-save'){row=(S.goals||[]).find(g=>g.id==id);modal(row?'Edit savings goal':'Create a savings goal','Give your savings a purpose.',field('title','Goal name','text',row?.title||'')+field('target','Target (__CURRENCY__)','number',row?row.target/100:'','min="0.01" step="0.01"')+(parent()?field('match_percent','Parent matching reward (%)','number',row?.match_percent||0,'min="0" max="100" step="1"'):'')+(parent()?'<p>Matching is paid once, after the goal is fully saved and you approve it.</p>':''),'goal-save',id,'Save goal');}
else if(action==='goal-contribute'||action==='goal-withdraw'){row=S.goals.find(g=>g.id==id);const saving=action==='goal-contribute';modal(saving?'Save for '+e(row.title):'Release goal savings',saving?'Move money from your wallet into this savings goal.':'Move money from this goal back to your wallet.',amountField(),action,id,saving?'Save money':'Release money');}
else if(action==='goal-match'){row=S.goals.find(g=>g.id==id);modal('Pay matching reward?',`${coins(Math.round(row.target*row.match_percent/100))} __CURRENCY__ will be paid once from the bank to ${e(S.child)}. This rewards reaching ${e(row.title)}.`,'',action,id,'Pay reward');}
else if(action==='bank-transfer')modal('Transfer from bank to child',`Available in bank: ${coins(S.bank_balance||0)} __CURRENCY__. The amount will be deducted from your bank and added to the chosen child's wallet.`,`<label>To child<select name="child_id">${S.children.map(c=>`<option value="${c.id}" ${c.id===S.child_id?'selected':''}>${e(c.name)}</option>`).join('')}</select></label>${amountField()}${field('reason','Reason','text','Transfer from bank')}<input type="hidden" name="direction" value="add">`,'adjust','','Transfer funds');else if(action==='bank-fund')modal('Add money to the bank','This stays in your private bank balance. No child receives it. Record money you have set aside; this app does not move real money.',amountField()+field('reason','Note'),'bank-fund','','Add to bank');else if(action==='adjust')modal('Give __CURRENCY__ to '+e(S.child)+'.','These __CURRENCY__ go to '+e(S.child)+'’s wallet. Money added to this wallet comes from your bank balance; money removed returns to the bank. Every change is recorded.',`<label>Action<select name="direction"><option value="add">Add __CURRENCY__</option><option value="remove">Remove __CURRENCY__</option></select></label>${amountField()}${field('reason','Reason')}`,'adjust','','Save transaction');
else if(action==='cashout-request')modal('Request a cash-out.',`You have ${coins(S.wallet)} __CURRENCY__ (${usd(S.wallet)}) available. These __CURRENCY__ will be held until your parent responds.`,field('amount','Amount in __CURRENCY__','number','','min="1" step="1"')+field('reason','What is this for?','text','Cash out'),'cashout-request','','Request cash-out');
else if(action==='cashout-cancel')modal('Cancel this request?','The held __CURRENCY__ will return to your wallet.','','cashout-cancel',id,'Cancel request');
else if(action==='account-add')modal('Add a child.','Create a separate wallet and sign-in for another child.',field('name','Child name')+field('username','Username','text','','minlength="3" maxlength="32" autocomplete="off"')+field('password','Child password','password','','minlength="10" autocomplete="new-password"')+field('current_password','Your current parent password','password','','autocomplete="current-password"'),'account-add','','Create child account');
else if(action==='account-save'){row=S.accounts.find(x=>x.id==id);modal('Manage '+e(row.name)+'’s account.','Changing an account signs that person out. Leave the new password blank to keep it.',field('name','Name','text',row.name)+field('username','Username','text',row.username,'minlength="3" maxlength="32"')+'<label>New password (optional)<input name="password" type="password" minlength="10" autocomplete="new-password"></label>'+field('current_password','Your current parent password','password','','autocomplete="current-password"'),'account-save',id,'Save account');}
else if(action==='transfer')modal('Move your __CURRENCY__.','Transfer between your wallet and savings.',`<label>From<select name="source"><option value="wallet">Wallet (${coins(S.wallet)} __CURRENCY__)</option><option value="savings">Savings (${coins(S.savings)} __CURRENCY__)</option></select></label>${amountField()}`,'transfer','','Transfer');
else if(action==='reverse')modal('Reverse this transaction?','The original stays in your history. A new, opposite entry will be added.',field('reason','Reason for reversal'),'reverse',id,'Reverse transaction');
else if(['chore-save','reward-save'].includes(action)){row=(action==='chore-save'?S.chores:S.rewards).find(x=>x.id==id);modal(action==='chore-save'?'Set a chore reward.':'Add something to save for.','Pending requests keep their original __CURRENCY__ amount.',`${field('title','Name','text',row?.title||'')}${field('amount',action==='chore-save'?'Reward (__CURRENCY__)':'Price (__CURRENCY__)','number',row?(row.reward??row.price)/100:'','min="0.01" max="100000000" step="0.01"')}${action==='chore-save'?`<label>Repeats<select name="recurrence">${[['anytime','Whenever needed'],['once','One time'],['daily','Daily'],['weekly','Weekly']].map(([v,t])=>`<option value="${v}" ${(row?.recurrence||'anytime')===v?'selected':''}>${t}</option>`).join('')}</select></label><label>First / next due date<input type="date" name="due_date" value="${e(row?.due_date||S.today)}"></label><p>Daily and weekly chores return on their next due date after approval. Dates use New York time.</p>`:''}${row?`<label class="check"><input name="active" type="checkbox" ${row.active?'checked':''}>Available</label>`:''}`,action,id,'Save');}
else if(action==='investment-save'){row=S.investments.find(x=>x.id==id);modal('Choose an investment.','Use a stock or ETF supported by your market data provider.',`${field('name','Name','text',row?.name||'')}${field('symbol','Ticker','text',row?.symbol||'',row?'readonly':'')}<label>Risk<select name="risk">${['Lower','Balanced','Growth','High'].map(r=>`<option ${r===row?.risk?'selected':''}>${r}</option>`).join('')}</select></label>${row?`<label class="check"><input type="checkbox" name="enabled" ${row.enabled?'checked':''}>Available for new purchases</label>`:''}`,action,id,'Save');}
else if(action==='committee-save'){row=S.committees.find(x=>x.id==id);const a=row?JSON.parse(row.allocations):{};modal('Build an investment mix.','Percentages must add to 100. Existing purchases keep their original mix.',`${field('name','Mix name','text',row?.name||'')}${[...S.investments,{id:'cash',name:'Uninvested cash (stays idle; no automatic investing)'}].map(i=>field('allocation_'+i.id,e(i.name)+' (%)','number',a[i.id]||0,'min="0" max="100" step="0.01"')).join('')}${row?`<label class="check"><input type="checkbox" name="enabled" ${row.enabled?'checked':''}>Available</label>`:''}`,action,id,'Save mix');}
else if(action==='buy'||action==='buy-committee'){row=(action==='buy'?S.investments:S.committees).find(x=>x.id==id);modal('Invest in '+e(row.name),`Available: ${coins(S.wallet)} __CURRENCY__. Choose how much to invest.`,`${field('amount','Amount to invest (__CURRENCY__)','number','',`min="0.01" max="${S.wallet/100}" step="0.01" id="investment-amount"`)}<button type="button" class="ghost small" data-action="invest-max">Use all available</button><p id="investment-preview" aria-live="polite">Enter an amount to see how many shares you will buy.</p><p>100 __CURRENCY__ = 1 simulated share. Fractional shares are allowed.</p><input type="hidden" name="type" value="${action==='buy'?'investment':'committee'}">`,'buy',id,'Invest __CURRENCY__');}

else if(action==='sell'){row=S.positions.find(x=>x.id==id);modal('Sell '+e(row.name)+'?',`Sell the entire position for approximately ${coins(row.value)} __CURRENCY__, based on the most recent available quotes. The final value is calculated when you confirm.`,'','sell',id,'Sell investment');}
else if(action==='redeem'){row=S.rewards.find(x=>x.id==id);modal('Request '+e(row.title)+'?',`${coins(row.price)} __CURRENCY__ will be deducted when your parent approves. Pending requests do not reserve your balance.`,'','redeem',id,'Request reward');}
else if(action==='chore-complete')modal('All finished?','Send this chore to your parent for approval. __CURRENCY__ arrive after they approve.','','chore-complete',id,'Send for approval');
else if(action==='chore-revise'){row=(S.pending_chores||[]).find(c=>c.id==id);if(!row)return;modal('Send back to '+e(row.child_name),'Explain what needs fixing. No reward is paid until you accept the resubmission.',field('note','What needs to be fixed?')+`<input type="hidden" name="child_id" value="${row.child_id}"><input type="hidden" name="revise" value="true">`,'chore-review',id,'Send back');}
else if(action==='chore-approve'||action==='chore-decline'){row=(S.pending_chores||[]).find(c=>c.id==id);if(!row){toast('This chore was already reviewed.');load();return}const approve=action==='chore-approve';modal(approve?'Accept & pay '+e(row.child_name)+'?':'Decline this chore?',approve?`${coins(row.reward)} __CURRENCY__ will move from your bank to ${e(row.child_name)} for ${e(row.title)}.`:'The child will not be paid for this submission.',`<input type="hidden" name="child_id" value="${row.child_id}"><input type="hidden" name="approve" value="${approve}">`,'chore-review',id,approve?'Accept & pay':'Decline');}
else if(/^(chore|redemption|cashout)-(approve|decline)$/.test(action)){const [type,decision]=action.split('-');modal(decision==='approve'?'Approve this request?':'Decline this request?',decision==='approve'?(type==='chore'?'The reward will be added to the wallet.':type==='cashout'?'Confirm that you will pay '+usd(S.cashouts.find(x=>x.id==id).amount)+' to your child. The held __CURRENCY__ will be redeemed. This app does not transfer real money.':'__CURRENCY__ will be deducted. Please arrange the reward with your child.'):(type==='cashout'?'The held __CURRENCY__ will return to the wallet.':'The request will be marked declined without moving any __CURRENCY__.'),`<input type="hidden" name="approve" value="${decision==='approve'}">`,type+'-review',id,decision==='approve'?'Approve':'Decline');}}
document.addEventListener('click',async ev=>{const el=ev.target.closest('button');if(!el)return;if(el.dataset.chartMode){chartMode=el.dataset.chartMode;render();return}if(el.dataset.chartRange){chartRange=el.dataset.chartRange;render();return}if('chartAsset' in el.dataset){chartAsset=el.dataset.chartAsset;render();return}if(el.dataset.page){page=el.dataset.page;render();return}const a=el.dataset.action;if(!a)return;if(a==='invest-max'){$('#investment-amount').value=(S.wallet/100).toFixed(2);updateInvestmentPreview();return}if(a==='close'){$('#dialog').close();return}if(a==='reload'){load();return}if(a==='export'){const safe=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const csv=[['ID','Date','Type','Reason','Wallet __CURRENCY__','Savings __CURRENCY__','Held __CURRENCY__'],...S.ledger.map(t=>[t.id,t.at,t.kind,t.reason,t.wallet/100,t.savings/100,(t.held||0)/100])].map(r=>r.map(v=>safe(currencyText(v))).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='wealth-trainer-ledger.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(a==='backup-now'){el.disabled=true;try{await api(a,{});await load();toast('Backup saved to the backups folder.')}catch(err){toast(err.message);el.disabled=false}return}if(a==='logout'||a==='refresh-prices'){el.disabled=true;try{const result=await api(a,{});await load();if(a==='refresh-prices')toast(`Updated ${result.updated.length} quotes.${result.failed.length?' Could not retrieve: '+result.failed.join(', ')+'. Yahoo may be unavailable temporarily; automatic retries are enabled.':''}`)}catch(err){toast(err.message);el.disabled=false}return}openAction(a,el.dataset.id)});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target;const data=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type=submit]');submit.disabled=true;form.querySelector('.error').textContent='';try{if(form.id==='auth-form'){const setup=form.dataset.setup==='true';await api(setup?'setup':'login',data);await load();if(setup)toast('Your family bank is ready. Sign in to begin.');return}let action=form.id==='settings-form'?'settings':form.dataset.action;if(form.dataset.id)data.id=Number(form.dataset.id);for(const key of ['active','enabled']){if(form.elements[key])data[key]=form.elements[key].checked}if('approve'in data)data.approve=data.approve==='true';if('revise'in data)data.revise=data.revise==='true';if(action==='committee-save'){data.allocations={};for(const [k,v] of Object.entries(data)){if(k.startsWith('allocation_')&&Number(v)>0)data.allocations[k.slice(11)]=v}}await api(action,data);if($('#dialog').open)$('#dialog').close();await load();toast('Saved. Your family bank is up to date.')}catch(err){form.querySelector('.error').textContent=err.message;submit.disabled=false}});
function updateInvestmentPreview(){const input=$('#investment-amount'),preview=$('#investment-preview');if(!input||!preview)return;const amount=Number(input.value);preview.textContent=!input.value||!Number.isFinite(amount)||amount<=0?'Enter an amount to see how many shares you will buy.':amount>S.wallet/100?currencyText('This exceeds your available '+coins(S.wallet)+' __CURRENCY__.'):currencyText('You will buy '+(amount/100).toLocaleString(undefined,{maximumFractionDigits:4})+' simulated shares for '+coins(Math.round(amount*100))+' __CURRENCY__. Remaining balance: '+coins(S.wallet-Math.round(amount*100))+' __CURRENCY__.');}
document.addEventListener('input',ev=>{if(ev.target.id==='investment-amount')updateInvestmentPreview();if(ev.target.id==='search'){const pos=ev.target.selectionStart;query=ev.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('change',async ev=>{if(ev.target.id==='child-picker'){document.querySelectorAll('#app button').forEach(b=>b.disabled=true);selectedChild=ev.target.value;chartAsset='';chartRange='ALL';page='overview';query='';filter='all';await load();return}if(ev.target.id==='filter'){filter=ev.target.value;render()}});
load();

setInterval(()=>{if(S?.user&&!$('#dialog').open&&!$('.optional-controls[open]')&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))load()},60000);
